# v625: the Commander tab as a header and picture tiles (each its own page) and the Elements page remastered. See p625_cmd.js.
import sys, re
P = sys.argv[1] if len(sys.argv) > 1 else 'docs/index.html'
s = open(P, encoding='utf-8').read()
def rep(a, b, n=1):
    global s
    c = s.count(a); assert c == n, (c, a[:90]); s = s.replace(a, b)
js = open('tools/patches/p625_cmd.js', encoding='utf-8').read()
css = ('.ctiles{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.ctile{position:relative;overflow:hidden;display:flex;flex-direction:column;align-items:flex-start;gap:4px;min-height:104px;padding:12px;border-radius:16px;border:1px solid color-mix(in srgb,var(--c) 40%,transparent);background:radial-gradient(90% 80% at 85% 15%,color-mix(in srgb,var(--c) 26%,transparent),transparent 65%),linear-gradient(160deg,#152230,#0b121c);color:#eef5f9;text-align:left;cursor:pointer;box-shadow:0 3px 0 #0a0d12}'
  '.ctile .ctic{width:34px;height:34px;color:var(--c);filter:drop-shadow(0 0 8px color-mix(in srgb,var(--c) 60%,transparent))}.ctile .ctic svg{width:34px!important;height:34px!important;color:var(--c)!important}.ctile b{font-size:16px;font-family:var(--f-display);margin-top:auto}.ctile small{font-size:12px;color:var(--muted)}.ctile small .shard{font-size:12px}.ctile .ctdots{position:absolute;right:12px;top:14px;display:flex;gap:4px}.ctile .ctdots i{width:9px;height:9px;border-radius:50%;background:var(--d);box-shadow:0 0 6px var(--d)}.ctile .ctbad{position:absolute;right:10px;top:10px;padding:2px 8px;border-radius:999px;background:#ffcf5a;color:#1a1020;font:700 11px var(--f-display)}'
  '.cpghd{display:flex;align-items:center;gap:10px;margin-bottom:6px}.cpghd h2{margin:0;font-size:20px}.cpg{padding-bottom:84px}'
  '.elpage{display:flex;flex-direction:column;gap:10px}.elpage>*{flex-shrink:0}.elock{display:grid;gap:5px;padding:10px 12px;border-radius:12px;border:1px solid rgba(255,207,90,.4);background:rgba(255,207,90,.07)}.elock b{color:#ffcf5a;font-size:14px}.elock small{font-size:11.5px;color:var(--muted)}'
  '.runes.elw .rw{transition:transform .35s cubic-bezier(.2,1.4,.4,1),opacity .3s,filter .3s;opacity:.62;filter:saturate(.7)}.runes.elw .rw.sel{opacity:1;filter:none;transform:scale(1.12);z-index:3}'
  '.elchips{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:5px}.elchip{display:flex;flex-direction:column;align-items:center;gap:2px;padding:6px 2px;border-radius:10px;border:1px solid color-mix(in srgb,var(--c) 35%,transparent);background:rgba(8,14,24,.7);color:var(--muted);font-size:10.5px;cursor:pointer}.elchip i{width:10px;height:10px;border-radius:50%;background:var(--c);box-shadow:0 0 6px var(--c)}.elchip b{color:var(--c);font-size:13px}.elchip.on{border-color:var(--c);background:color-mix(in srgb,var(--c) 14%,transparent);color:#fff}'
  '.elpanel{padding:12px;border-radius:14px;border:1px solid color-mix(in srgb,var(--c) 45%,transparent);background:radial-gradient(70% 60% at 50% 0%,color-mix(in srgb,var(--c) 18%,transparent),transparent 70%),#0a121d}.elph{display:flex;justify-content:space-between;align-items:baseline}.elph b{font-size:17px;color:var(--c);font-family:var(--f-display)}.elph span{color:#ffcf5a;letter-spacing:2px;font-size:13px}'
  '.elstones{display:flex;flex-wrap:wrap;gap:7px;margin:10px 0 6px}.elstones i{width:26px;height:30px;clip-path:polygon(50% 0,100% 25%,100% 75%,50% 100%,0 75%,0 25%);background:#1d2530}.elstones i.on{background:linear-gradient(160deg,#fff,var(--c) 45%,color-mix(in srgb,var(--c) 45%,#000));box-shadow:0 0 10px var(--c)}.elstones i.pop{animation:fgpop .9s cubic-bezier(.2,1.7,.4,1)}'
  '.elline{font-size:12.5px;margin:2px 0 8px;color:var(--muted)}.elline b{color:#e9f2ff}.elbtns{display:grid;gap:6px}.elbt2{display:grid;grid-template-columns:1fr 1fr;gap:6px}.elcost{font-size:10.5px;color:var(--muted);text-align:center}'
  '.elsrc{padding:10px 0 0}.elsh{display:flex;justify-content:space-between;align-items:center}.elsh span{font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:#e2cf94}.elsr{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:5px;margin-top:6px}'
  '.elboss{position:relative;display:flex;flex-direction:column;align-items:center;gap:1px;padding:4px 2px;border-radius:10px;border:1px solid color-mix(in srgb,var(--c) 35%,transparent);background:#0a111b;color:#dce7ef;cursor:pointer;overflow:hidden}.elboss img{width:100%;aspect-ratio:1;object-fit:cover;border-radius:7px}.elboss small{font-size:9px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%}.elboss i{font-style:normal;font-size:9px;color:var(--c);font-weight:700}'
  '#coach>*{transition:scale .25s ease,filter .25s ease}#coach.mini>*{scale:.7;transform-origin:20% 50%;filter:opacity(.6);pointer-events:none}#coach.mini .cpt,#coach.mini .cpx{display:none}\n')
i = s.index('</style>', s.index('#celeb{position:fixed')); s = s[:i] + css + s[i:]
# the new Elements page replaces mElem
a = s.index('function mElem() {'); b = s.index('\nfunction mSave() {', a); s = s[:a] + js.rstrip() + s[b:]
# wheels select instead of socketing at once; the chosen one comes forward
rep('return `<button class="rw ${e}${on >= sl ? " full" : ""}${fx ? " burst" : ""}" style="--rc:${col};--rh:${hi}" data-act="runeSlot" data-e="${e}" aria-label="${d.n} ring, tier ${tier}, ${on} of ${sl} socketed, ${spare} spare. Tap to socket a rune.">',
    'return `<button class="rw ${e}${on >= sl ? " full" : ""}${fx ? " burst" : ""}${(ELEM[G.elSel] ? G.elSel : "fire") === e ? " sel" : ""}" style="--rc:${col};--rh:${hi}" data-act="elSel" data-e="${e}" aria-label="${d.n} ring, tier ${tier}, ${on} of ${sl} socketed, ${spare} spare. Tap to choose it.">')
rep('G.runeFx = { e, i: runeOn(e) - 1, t: now() }; SFX.rune(e, full);', 'G.runeFx = { e, i: runeOn(e) - 1, t: now() }; G.elSel = e; try { wsLoad(); if (!wsPlay(full ? "rn_ring" : "rn_socket")) SFX.rune(e, full); } catch (x) { SFX.rune(e, full); }')
# the Commander tab: header, then tiles; a tile opens its own page
a = s.index('    ${acc("alliance", ic(MI.wings), "Alliance"'); b = s.index('    ${duelOwner() ? `<button class="btn ghost wide" data-act="fbInbox">', a)
tiles = ('    ${(() => { const rn = Object.values(S.runes || {}).reduce((a, b) => a + b, 0), tl = (k, icon, st, extra) => `<button class="ctile" style="--c:${CMD_PAGES[k] ? CMD_PAGES[k][1] : "#ffcf5a"}" data-act="${CMD_PAGES[k] ? "cmdPage" : k}" data-k="${k}"><span class="ctic">${icon}</span>${extra || ""}<b>${CMD_PAGES[k] ? CMD_PAGES[k][0] : "Supply Depot"}</b><small>${st}</small></button>`;\n'
         '      return `<div class="ctiles">${tl("alliance", ic(MI.wings), myAlly() ? `[${esc(myAlly().tag)}] ${esc(myAlly().name || "")}` : "Join or found one")}${tl("elements", ic(MI.shield, "#e06bd8"), rn ? `${rn} rune${rn > 1 ? "s" : ""} to socket` : `${Object.keys(ELEM).reduce((a, e) => a + runeOn(e), 0)} runes socketed`, `<span class="ctdots">${Object.keys(ELEM).map(e => `<i style="--d:${ELEM[e].col}"></i>`).join("")}</span>${rn ? `<span class="ctbad" style="top:auto;bottom:10px">${rn}</span>` : ""}`)}${tl("vshop", ic(MI.tag, "#c9a6ff"), `<span class="shard">◆ ${fmt(S.shards || 0)}</span>`)}${tl("depotOpen", ic(MI.tag), "Trades and contracts")}${tl("settings", ic(MI.grid), "Save, sound and account")}</div>`; })()}\n')
s = s[:a] + tiles + s[b:]
rep('    ${acc("settings", ic(MI.grid), "Settings", "", mSave() + mGame())}</div>`;\n}', '    </div>`;\n}')
rep('  return `<div class="cmd gstack">${profile}\n', '  if (CMD_PAGES[menu.page]) return `<div class="cmd gstack cpg"><div class="cpghd"><button class="btn ghost sm" data-act="cmdPage" data-k="">‹ Commander</button><h2>${CMD_PAGES[menu.page][0]}</h2></div>${cmdPageBody(menu.page)}</div>`; /* v625 */\n  return `<div class="cmd gstack">${profile}\n')
rep('menu.open[map[d.k] || d.k] = true; view = "cmd"; render(true); },', 'menu.open[map[d.k] || d.k] = true; { const pk = map[d.k] || d.k; menu.page = CMD_PAGES[pk] ? pk : null; } view = "cmd"; render(true); },\n'
    '  cmdPage: d => { menu.page = CMD_PAGES[d.k] ? d.k : null; if (menu.page === "settings") menu.open.settings = true; render(true); try { (document.scrollingElement || document.body).scrollTop = 0; const v = document.querySelector(".cmd"); if (v) v.scrollIntoView({ block: "start" }); } catch (e) {} }, elSel: d => { if (ELEM[d.e]) { G.elSel = d.e; render(true); } }, elInfo: () => { G.elInfo = !G.elInfo; render(true); }, /* v625 */')
rep('if (d.k === "depot" || d.k === "shop") return depotOpen();', 'if (d.k === "depot" || d.k === "shop") return depotOpen(); if (d.k === "inv") return ACT.invOpen();')
rep('const WSND = { fg_whoosh: 1.15,', 'const WSND = { rn_socket: 1.2, rn_ring: 1.2, fg_whoosh: 1.15,') # v625 the owner's rune sounds (docs/sfx/w_rn_*.mp3)
rep('fetch(`sfx/w_${k}.mp3?v=624`)', 'fetch(`sfx/w_${k}.mp3?v=625`)')
s2 = re.sub(r"GAME_V = 624\b", "GAME_V = 625", s); assert s2 != s; s = s2
open(P, 'w', encoding='utf-8').write(s); print('ok')
